import{t as e}from"./jsx-runtime-lw2jiZar.js";import{A as t,C as n,E as r,H as i,M as a,N as o,O as s,P as c,_ as l,b as u,k as d,l as f,n as p,o as m,p as h,t as g}from"./shared-UmZHo_CQ.js";import{k as _}from"./index-3E7rQLz6.js";import{t as v}from"./CodeEditor-BZlrvoTL.js";var y=e(),b=`Этап 4 · Блок 14 · Подготовка базы и новой границы хранения`,x=[`class Shelf:`,`    def __init__(self):`,`        self.items = ["карта"]`,``,`    def load(self):`,`        return list(self.items)`,``,`class ShelfIndex:`,`    def __init__(self, shelf):`,`        self.shelf = shelf`,``,`    def count(self):`,`        return len(self.shelf.load())`,``,`shelf = Shelf()`,`index = ShelfIndex(shelf)`,`shelf.items.append("компас")`,`print(index.count())`].join(`
`),S=[`class StopBoard:`,`    def __init__(self, storage):`,`        self.storage = storage`,`        self.rows = storage.load()`,``,`    def count(self):`,`        return len(self.rows)`].join(`
`),C=[`class StopBoard:`,`    def __init__(self, storage):`,`        self.storage = storage`,``,`    def count(self):`,`        return len(self.storage.load())`].join(`
`);function w({module:e}){return(0,y.jsxs)(o,{children:[(0,y.jsx)(a,{variant:`project`,chip:e??b,title:`Граница чтения данных`,intro:`Planner уже хранит задачи в JSON и возвращает их через знакомые методы сервиса. Теперь отделим чтение от конкретного способа хранения, не меняя сами данные и не подключая базу к рабочему приложению.`,tags:[{icon:(0,y.jsx)(i,{size:14}),label:`PlannerService · репозиторий`},{icon:(0,y.jsx)(_,{size:14}),label:`JsonStorage · один файл`}]}),(0,y.jsxs)(c,{number:`00`,title:`Меняем способ запроса, сохраняя хранилище`,children:[(0,y.jsx)(s,{children:`В прежнем Planner сервис получает задачи из JSON через load, а затем выбирает нужный результат. Это уже рабочее постоянное хранение. Сейчас мы изменим границу между сервисом и данными: сервис будет просить операции чтения, а JSON останется за новым адаптером.`}),(0,y.jsx)(d,{variant:`connected`,items:[{title:`Точка старта`,description:`PlannerService, JsonStorage и общие API с CLI уже работают. Читающие методы сервиса получают полный список задач.`},{title:`Новый вопрос`,description:`Как отделить запрос списка, одной задачи или выборки от деталей файла, сохранив прежнее поведение?`},{title:`Результат`,description:`Чтение проходит через JsonTaskRepository, который использует то же JSON-хранилище; изменяющие методы пока остаются на прежнем пути.`}]}),(0,y.jsx)(`p`,{children:`Мы продолжаем тот же проект и сохраняем его публичные возможности. Изменится внутренняя граница доступа к данным. Сначала уточним, что именно неудобно в полном снимке, затем разделим роли слоёв и подготовим переход, который можно проверить на знакомых сценариях.`})]}),(0,y.jsxs)(c,{number:`01`,title:`От полного снимка к нужной операции`,children:[(0,y.jsx)(s,{children:`Сейчас list_tasks получает через storage.load весь список Task. Для get_task сервис также загружает список, а потом ищет одну задачу. select_tasks сначала получает всё, затем фильтрует, сортирует и ограничивает результат. Это понятная работающая схема, но в ней сервис знает, что для чтения нужно загрузить полный снимок.`}),(0,y.jsx)(v,{caption:`Текущая форма чтения в PlannerService`,code:`def list_tasks(self):
    return self.storage.load()`}),(0,y.jsx)(`p`,{children:`Когда данные лежат в файле, load читает и проверяет JSON, а затем создаёт предметные задачи. Так сохраняется нынешняя реализация. Позже запрос списка в SQLite сможет обратиться к строкам таблицы напрямую, но сервису не придётся решать, как устроены SQL-запросы. Для этого мы вводим предметные операции чтения на отдельной границе.`}),(0,y.jsx)(`p`,{children:`Представим библиотечный каталог. Если нужен один экземпляр книги, библиотекарь может попросить архивариуса найти его по шифру. Ему не обязательно принимать весь склад карточек и самостоятельно перебирать их. В приложении сервис формулирует запрос, а репозиторий обращается к данным. Аналогия помогает увидеть разделение просьбы и способа поиска, но не обещает, что файловое хранилище перестанет читать весь JSON.`}),(0,y.jsx)(`p`,{children:`Это важное ограничение перехода. Сам адаптер не ускоряет JSON и не устраняет ограничения полного снимка. Он меняет место, где сервис договаривается о чтении. В следующем блоке такую же операцию можно будет реализовать через SQL, сохранив понятные сервису имена и результаты.`}),(0,y.jsx)(l,{code:x,output:`2`,hint:`Мы создаём индекс до изменения полки. Посмотрите, когда count вызывает load.`}),(0,y.jsx)(`p`,{children:`В независимом примере индекс не запоминает список при создании. Он запрашивает текущее содержимое полки в момент подсчёта, поэтому видит добавленный компас. Этот принцип пригодится адаптеру: объект может сохранять ссылку на источник, но свежие данные получает при вызове операции, а не копирует в конструкторе.`})]}),(0,y.jsxs)(c,{number:`02`,title:`Сервис, репозиторий и HTTP имеют разные роли`,children:[(0,y.jsx)(s,{children:`Разделение не означает, что мы переносим весь код в новый класс. Каждый слой отвечает за свою часть. PlannerService сохраняет предметный сценарий и правила задачи. Репозиторий предлагает операции доступа к данным. JsonStorage читает и проверяет сериализованный файл. HTTP-обработчик переводит результат сервиса в ответ API, а CLI продолжает обращаться к тому же сервису.`}),(0,y.jsx)(g,{caption:`Занятие 85 · Путь запроса на чтение через прежний JSON`,orientation:`horizontal`,children:(0,y.jsxs)(m,{label:`От API или CLI к результату чтения`,className:`lesson85-reading-flow`,children:[(0,y.jsx)(f,{title:`HTTP API и CLI`,shape:`input-output`,children:(0,y.jsx)(`p`,{children:`Вызывают прежний метод Planner`})}),(0,y.jsx)(p,{label:`сценарий`}),(0,y.jsx)(f,{title:`PlannerService`,className:`lesson85-service-node`,children:(0,y.jsx)(`p`,{children:`Сохраняет правила и результат приложения`})}),(0,y.jsx)(p,{label:`операция чтения`}),(0,y.jsx)(f,{title:`JsonTaskRepository`,children:(0,y.jsx)(`p`,{children:`Предоставляет list, get, select, search, statistics`})}),(0,y.jsx)(p,{label:`актуальный снимок`}),(0,y.jsx)(f,{title:`JsonStorage`,shape:`terminator`,children:(0,y.jsx)(`p`,{children:`Читает один текущий JSON-файл`})})]})}),(0,y.jsx)(`p`,{children:`Результат возвращается по цепочке обратно как обычная Task, список задач или значения статистики. Репозиторий не принимает HTTP-запрос напрямую и не выбирает код ответа. CLI не обращается к файлу самостоятельно. Поэтому мы можем изменить способ чтения в одном месте, не создавая отдельный путь для каждого интерфейса.`}),(0,y.jsx)(`p`,{children:`Один и тот же PlannerService получает вызовы и из API, и из CLI. После рефакторинга оба интерфейса продолжают вызывать его прежние методы. Сервис может вернуть Task или сформировать свою ошибку, а HTTP-обработчик решает, как представить результат клиенту. Репозиторий остаётся ниже этой границы: он не импортирует FastAPI, не знает Pydantic-схем и не управляет командами терминала. Мы сохраняем эти роли, даже если способ чтения внутри хранилища изменится.`}),(0,y.jsx)(h,{prompt:`Сопоставим часть пути с её ответственностью.`,leftTitle:`Часть`,rightTitle:`Ответственность`,pairs:[{left:`HTTP API и CLI`,right:`Входят в общий сервисный сценарий`},{left:`PlannerService`,right:`Сохраняет предметные правила`},{left:`JsonTaskRepository`,right:`Предоставляет операции чтения`},{left:`JsonStorage`,right:`Читает и проверяет файл JSON`}],explanation:`Мы отделили публичный вход, предметный сценарий, договор доступа и файловую реализацию. При замене хранилища роли сервиса и интерфейсов не сливаются.`})]}),(0,y.jsxs)(c,{number:`03`,title:`Договор чтения сохраняет знакомые результаты`,children:[(0,y.jsx)(s,{children:`Репозиторий должен покрыть реальные читающие сценарии Planner, а не один показательный поиск. Мы оставляем публичные методы PlannerService прежними, но связываем каждый с соответствующей внутренней операцией. Аргументы, сортировка и значения результата продолжают означать то же, что и раньше.`}),(0,y.jsx)(t,{rows:[[`list_tasks → list`,`Возвращает все Task в прежнем порядке снимка.`],[`get_task → get`,`Возвращает одну Task; отсутствие на уровне чтения обозначается None.`],[`select_tasks → select`,`Сохраняет фильтр is_done, порядок по id и limit.`],[`search_tasks → search`,`Сохраняет strip, lower и поиск буквальной подстроки.`],[`get_statistics → statistics`,`Возвращает прежние значения all, open и done.`]]}),(0,y.jsx)(`p`,{children:`Это не смена названий, которую должны заметить клиенты. API и CLI по-прежнему вызывают list_tasks, get_task и остальные публичные методы. Новые имена описывают договор между сервисом и репозиторием. Они позволяют видеть, какая операция нужна сценарию, не раскрывая способ хранения.`}),(0,y.jsx)(`p`,{children:`Для выборки порядок тоже часть поведения. Сначала учитывается фильтр is_done, затем задачи упорядочиваются по id, а limit ограничивает уже отсортированный список. Поиск обрезает пробелы по краям запроса, приводит его к нижнему регистру и проверяет буквальное вхождение в title. Пустой после обрезки запрос возвращает пустой список. Мы сохраняем нынешние правила, потому что занятие меняет границу доступа, а не определение поиска.`}),(0,y.jsx)(`p`,{children:`Пустой список и отсутствие одной задачи похожи только на первый взгляд. list или select может законно вернуть [], если совпадений нет. get отвечает на вопрос об одной записи и возвращает None, когда её не существует. Сервис использует это различие: пустой результат списка остаётся обычным результатом, а неизвестный id становится предметной ошибкой. Так адаптер не выдумывает объект и не принимает решение за вызывающий слой.`}),(0,y.jsx)(u,{question:`Что возвращает repository.get, если записи с таким id нет?`,options:[`None, а решение об ошибке остаётся сервису.`,`TaskNotFoundError, чтобы репозиторий сам выбрал бизнес-ответ.`,`Пустой список, как для запроса всех задач без результатов.`],correctIndex:0,explanation:`None означает отсутствие одной записи на границе чтения. PlannerService по-прежнему проверяет id и превращает отсутствие в предметную ошибку; HTTP-слой уже представляет эту ошибку клиенту.`})]}),(0,y.jsxs)(c,{number:`04`,title:`JSON-адаптер является мостом, а не вторым складом`,children:[(0,y.jsx)(s,{children:`JsonTaskRepository оборачивает переданный JsonStorage и выражает его возможности через операции чтения. Сам JsonStorage продолжает отвечать за файл, разбор JSON и проверку записей. Новый класс не создаёт собственный список задач, JSON-файл или кеш.`}),(0,y.jsx)(`p`,{children:`Такой адаптер похож на переходник между разъёмом прибора и розеткой. Прибору важен совместимый вход, а переходник согласует форму соединения с доступной сетью. Он не становится новой электростанцией и не создаёт запасную сеть. Здесь сервис просит get или select, а JSON-адаптер выражает эту просьбу через существующий load. Предел аналогии в том, что адаптер выполняет настоящую логику выбора записей, а не только меняет форму разъёма.`}),(0,y.jsx)(`p`,{children:`Чтобы ответ оставался актуальным, операция читает данные у storage при вызове. Если загрузить список один раз в __init__ и затем постоянно перебирать его, репозиторий сохранит старое состояние. Дополнительное состояние в памяти здесь не нужно: JsonStorage уже возвращает список предметных объектов, и репозиторий выбирает из свежего результата.`}),(0,y.jsx)(n,{code:S,question:`Почему доска перестаёт видеть новые остановки после создания объекта?`,options:[`Конструктор сохраняет один снимок, а count больше не обращается к storage.`,`Метод len нельзя вызвать внутри метода класса.`,`Storage не может вернуть список из метода load.`],correctIndex:0,explanation:`Мы нашли снимок, загруженный слишком рано. Для свежего результата операция должна обратиться к текущему источнику, а не пользоваться списком, запомненным в конструкторе.`,fix:C}),(0,y.jsx)(r,{tone:`info`,children:`JSON-адаптер всё ещё читает полный JSON-снимок. Мы готовим ясный договор для будущей реализации, но пока не объявляем файловое чтение SQL-запросом или оптимизацией.`})]}),(0,y.jsxs)(c,{number:`05`,title:`Один источник данных допускает два временных пути`,children:[(0,y.jsx)(s,{children:`В этом шаге меняется только чтение. Поэтому PlannerService временно сохраняет прежний путь для изменяющих методов и получает операции чтения через новый адаптер. Эти пути должны указывать на один и тот же объект JsonStorage и один JSON-файл.`}),(0,y.jsx)(`p`,{children:`Представим одну кухню с двумя проходами. Один проход пока обслуживает готовку, другой уже ведёт к месту выдачи. Если оба ведут к одной кухне, приготовленное блюдо появится у выдачи. Если для второго прохода открыть соседнюю кухню, мы получим две копии состояния. Так же и здесь: временно отличаются способы чтения и записи, но не данные и не экземпляр storage.`}),(0,y.jsx)(`p`,{children:`Например, add_task пока работает прежним образом: загружает список, добавляет Task и сохраняет его. Следующее чтение через репозиторий вызывает load у того же storage и сразу видит новую задачу. То же происходит после внешнего save через этот объект. Репозиторий не должен держать отдельный снимок, а сервис не должен создавать новый JsonStorage ради чтения.`}),(0,y.jsx)(`p`,{children:`Промежуточное состояние ограничено целью занятия. Мы не делаем SQL репозиторий основным, не выбираем новый provider и не переносим запись досрочно. На следующем шаге изменяющие операции перейдут через тот же договор, после чего прямые load и save будут удалены из сервиса. Сейчас их наличие ожидаемо и не означает, что мы забыли обновить практику.`}),(0,y.jsx)(u,{question:`Что связывает старую запись и новое чтение в промежуточном состоянии?`,options:[`Один и тот же объект JsonStorage под обоими путями.`,`Два JsonStorage, которые случайно используют одинаковое имя файла.`,`Снимок задач, скопированный в конструктор PlannerService.`],correctIndex:0,explanation:`Мы сохраняем один источник и меняем путь доступа к нему. Второй объект или кеш может разойтись с действующей записью и создать впечатление двух разных состояний.`})]}),(0,y.jsxs)(c,{number:`06`,title:`Правила и границы ошибок остаются у своих слоёв`,children:[(0,y.jsx)(s,{children:`Репозиторий чтения сообщает, что удалось найти в данных. Он не решает, корректен ли id для Planner, и не выбирает, как показать отсутствие через HTTP. Эти решения уже принадлежат существующим слоям, поэтому мы сохраняем их при переходе.`}),(0,y.jsx)(`p`,{children:`PlannerService проверяет тип и положительность id до обращения к репозиторию. Если get вернул None, сервис поднимает уже знакомую TaskNotFoundError. HTTP-обработчик сохраняет прежнее отображение ошибки, а CLI получает прежний предметный результат. Репозиторий не импортирует FastAPI и не создаёт HTTPException.`}),(0,y.jsx)(`p`,{children:`Формой результата также остаётся предметная Task, а не ORM-строка TaskRow. Предыдущее чтение отдельно подготовило это преобразование для слоя базы. В текущем переходе JSON-адаптер возвращает те же поля задачи, включая внутренние tags, и не добавляет служебные значения в HTTP-ответ. Значит, сервисный договор остаётся устойчивым, пока меняется только способ доступа к сохранённым данным.`}),(0,y.jsx)(`p`,{children:`Файловые ошибки также остаются заметными. JsonStorage по-прежнему сообщает StorageError, когда чтение невозможно или JSON имеет неверную форму. Новый адаптер не превращает сбой чтения в пустой список и не объявляет задачу отсутствующей. Иначе API и CLI могли бы показать правдоподобный, но неверный результат.`}),(0,y.jsx)(`p`,{children:`Сборка продолжает принимать переданный тестовый storage и по умолчанию создаёт JsonStorage для рабочего пути. Адаптация выполняется явно в существующем конструкторе сервиса: он сохраняет storage для временной записи и связывает с ним репозиторий для чтения. Мы не добавляем второй PlannerService, не меняем fixtures и не запускаем чтение файла при одной только сборке объекта.`}),(0,y.jsx)(`p`,{children:`Проверки должны подтвердить обе стороны перехода. Мы сравним результаты чтения до и после, проверим пустой и заполненный список, найденный и неизвестный id, фильтр, порядок, limit, поиск и статистику. Затем посмотрим, что прежняя запись видна новому пути, а API, CLI и preferences продолжают работать с теми же данными. Изменения к заданиям, SQL-provider и новой базе в эту проверку не входят.`})]}),(0,y.jsxs)(c,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,y.jsx)(s,{children:`Мы изменим только путь чтения существующего Planner. В результате сервис будет обращаться к операциям репозитория, а единственным рабочим хранилищем останется прежний JSON.`}),(0,y.jsx)(d,{variant:`connected`,items:[{title:`Проследим исходный путь`,description:`Зафиксируем, какие читающие и изменяющие методы сейчас вызывают load и save, и сверим прежние результаты.`},{title:`Опишем договор чтения`,description:`Свяжем list, get, select, search и statistics с текущими результатами Planner и границами предметных ошибок.`},{title:`Добавим JSON-адаптер`,description:`Подключим JsonTaskRepository к тому же переданному storage и переведём на его операции только читающие методы сервиса.`},{title:`Проверим актуальность данных`,description:`Сравним чтение после прежнего добавления и внешнего save через тот же объект хранилища.`},{title:`Сохраним прежний Planner`,description:`Повторно проверим фильтры, поиск, статистику, JSON API, CLI и preferences без подключения SQL.`}]}),(0,y.jsx)(`p`,{children:`Мы начнём с подтверждённого состояния сервиса и разложим работу на один договор и один адаптер. Каждое чтение будет получать актуальный результат из прежнего JSON, а запись до следующего занятия останется на старом пути. Все проверки используют отдельные тестовые данные и подтверждают сохранение текущих контрактов.`}),(0,y.jsx)(`p`,{children:`В итоге мы сможем заменить реализацию доступа к данным, не переписывая публичные методы и интерфейсы Planner. Следующее занятие завершит перенос изменений на ту же границу. Только после этого SQL-репозиторий начнёт постепенно реализовывать уже подготовленные операции.`})]})]})}export{w as Lesson85};